def wr(p,v):p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
assert sha(P)==SHA;book=fitz.open(P);out=B/'2027-yz250-top-end-power-valve-bench-v1.procedure.json'
if out.exists():assert json.loads(out.read_text(encoding='utf8'))['publication_status']!='APPROVED','Frozen artifact'
steps=[]
def st(id,title,text,pages,record=False):
 steps.append(dict(id=id,title=title,instruction=text,depends_on=[steps[-1]['id']] if steps else [],source_pdf_pages=pages,source_links=[URL+'#page='+str(n) for n in pages],diagram_reference_required=True,record_required=record,verification=['Record the actual measurements, parts disposition or verification requested.'] if record else ['Confirm the described assembly and checks are complete before advancing.'],origin='Exact D69-2819U-12 OEM source; prepared-engine boundary and saved measurement records are explicit authored workflow adaptations.'))
st('entry','Confirm the prepared engine','Confirm exact stock US 2027 YZ250V and record the engine identity and work reason. This begins with a cold, clean engine securely supported on a suitable bench, coolant already drained, exhaust, carburetor, spark-plug cap, head-side coolant hose and upper engine brackets already detached by the separate engine-access operation. Crankcases remain closed; crankshaft/connecting rod and lower-end condition must already be accepted for this top-end job. Record that access handoff and any lower-end inspection concerns before proceeding. This procedure does not remove/refit the engine, overhaul the governor or authorize starting it.',[1,43,176],True)
st('head-off','Remove the head','Remove the spark plug. Loosen each of the six cylinder-head nuts half a turn at a time until all are loose, then remove them, their copper washers and the head. Retain dowels and discard the old head O-rings and copper washers for replacement. Keep the head and sealing surfaces protected.',[176,178])
st('pushrod-off','Disconnect the power-valve push rod','Remove the power-valve housing and its gasket. Insert the owner-tool-kit set pin into the illustrated mechanism before loosening the push-rod bolt; it protects the valve parts from the tightening/loosening load. Remove the bolt and push rod, keeping joint pieces in illustrated order, then REMOVE and account for the set pin. Never use the mechanism itself as the holding stop.',[176,178],True)
st('cylinder-off','Lift the cylinder','Remove the four cylinder nuts and carefully lift the cylinder off the piston and dowels. Support the piston/rod; retain the dowels and discard the old cylinder gasket. Keep dirt out of the open crankcase and place the cylinder on a protected work surface.',[176,178])
st('piston-off','Remove the piston and rings','Cover the crankcase opening with a clean rag before removing piston-pin clips so no clip can enter. Remove the clips, pin, piston and small-end bearing. Deburr the clip groove/pin-bore area if needed; if the pin still resists, use Yamaha 90890-01304 / YU-01304 piston-pin puller. Do not hammer the pin out. Open each ring end gap only enough with your fingers to lift the opposite side over the crown. Account for both clips and keep the crankcase protected.',[177,178],True)
st('valve-strip','Disassemble the cylinder power-valve mechanism','Using the exploded view, remove the power-valve cover, both side holders and old O-rings; retain the breather hose routing. Remove the thrust plate, holder 1 and shaft, then capture the link lever, two pulleys, springs and washers in their illustrated positions. Remove the link rod and both power valves 2, then holder 2 and power valve 1. Lay out left/right and spring/washer orientation before cleaning; do not mix or lose the small pieces. The separate crankcase governor remains intact.',[177,182,183],True)
st('head-inspect','Inspect the head','Remove combustion-chamber carbon with a rounded scraper; do not scratch the spark-plug threads or sealing face. Inspect head damage and water-jacket deposits/rust. Use a straightedge and feeler gauge across the sealing face as illustrated and record warpage; limit 0.03 mm. A damaged or over-limit head needs replacement or the separately completed OEM resurfacing operation before returning here; do not assemble it simply because the gasket is new.',[179],True)
st('bore-measure','Measure the cylinder','Inspect piston and bore for vertical scoring. With a bore gauge, record side-to-side and front-to-back measurements at the three illustrated heights D1–D6. Use their maximum as C. Standard bore 66.400–66.414 mm; wear limit 66.464 mm. Follow OEM disposition for scoring or an out-of-specification cylinder: replace the cylinder and piston/rings as a set. Keep these actual measurements with the job.',[43,179,180],True)
st('piston-measure','Measure piston clearance','Measure piston skirt diameter with a micrometer at the illustrated orientation, 17.5 mm from the skirt bottom. Standard diameter is 66.352–66.367 mm. Calculate actual maximum cylinder bore C minus measured piston diameter: specified clearance 0.045–0.050 mm. Record all three values. Replace out-of-specification parts following the OEM piston/ring-set and cylinder disposition; do not substitute nominal dimensions for a measurement.',[43,179,180],True)
st('size-match','Match the replacement size','Read and record actual cylinder and piston grade marks. OEM matching is A to A/red (piston 66.352–66.355 mm), B to B/orange (66.356–66.359), C to C/green (66.360–66.363), D to D/purple (66.364–66.367). Cylinder grades are A 66.400–66.402, B 66.404–66.406, C 66.408–66.410, D 66.412–66.414 mm. A purchased cylinder cannot be ordered by grade: select the piston to its actual mark and verify clearance. Record accepted or replacement parts before assembly.',[180,181],True)
st('rings-check','Measure both rings','Clean carbon from grooves/rings. Record top and second-ring side clearances: each standard 0.030–0.065 mm, limit 0.100 mm. Out-of-specification side clearance requires the piston and rings as a set. For each end-gap check, square the ring near the bottom of the cylinder using the piston crown, as illustrated, where wear is lowest. Measure and record the end gap; each limit is 0.95 mm. Replace an out-of-specification ring. The cited source does not state a new-ring minimum end gap; do not file rings to an invented target.',[43,44,181],True)
st('pin-check','Check pin and small-end bearing','Check the pin for blue heat discoloration or grooves; replace it and investigate fuel/engine mixing oil if present. Record pin OD (minimum limit 17.975 mm), piston pin-bore ID (maximum limit 18.040 mm), and ID minus OD clearance (standard 0.004–0.020 mm; limit 0.065 mm). Follow OEM replacement of out-of-specification pin/piston, including the pair for excessive clearance. Replace a heat-discolored small-end bearing; record its condition and accepted replacement parts.',[181,182],True)
st('valves-clean','Clean and inspect the power valves','Remove carbon from valves 1/2 and cylinder valve bores without a sharp tool or scratching the aluminum. Check valves, holder 1, link lever, pulleys, shaft, link rod and washers for wear/damage; replace defects. Check both spring types for breakage. Record condition and replacements. The shaft seal must be sound; if damaged, resolve its correct holder/seal service before assembly rather than inventing a seal seating depth.',[177,182],True)
st('valve-main','Install the main valve','Lubricate power valve 1 with molybdenum disulfide OIL and install its gouge upward. Install holder 2; apply LOCTITE to its bolts and tighten to 6 N·m. Match the exact illustrated valve orientation.',[7,177,182,183])
st('valve-sides','Install side valves and link','Install both power valves 2, link rod and washers. Engage the cuts in both link-rod arm ends over the valve pins as illustrated. Tighten the link-rod screw to 6 N·m.',[177,183])
st('thrust-plate','Install the thrust plate first','Install the thrust plate onto the cylinder and tighten its screw to 6 N·m BEFORE installing the power-valve shaft.',[177,183])
st('shaft-stack','Assemble springs, pulleys and shaft','Install spring 1 onto the link lever, then into the cylinder with its stopper facing inward. Restore both pulleys, spring 2 pieces and washers exactly as illustrated. Apply molybdenum disulfide OIL to pulley grooves and lithium-soap grease to the shaft oil-seal lip. Insert the shaft with its cut aligned to the thrust plate, then rotate the cut upward. Record correct spring/washer order and cut orientation.',[7,177,183],True)
st('valve-lock','Secure and check valve movement','Install holder 1. Tighten the link-lever bolt FIRST to 4.0 N·m, then the pulley bolts to 4.0 N·m. Check power valve 1 for smooth movement. Repair or replace the cause of binding before closing the mechanism; record the movement check.',[184],True)
st('side-holders','Refit side holders and breather','Grease NEW side-holder O-rings with lithium-soap grease, then install both side holders with their projections upward. Tighten side-holder screws to 4.0 N·m. Refit the YPVS breather hose in its illustrated connection; keep it clear and unpinched.',[177,184])
st('valve-cover','Close the power-valve cover','Install a NEW cover gasket with its cut downward and seal-print side toward the cover. Install the cover with its arrow upward; tighten cover screws to 4.0 N·m.',[184])
st('rings-install','Install the rings','Fit the accepted correct rings without scratching the piston or damaging the rings. Align each ring gap with its locating pin and confirm smooth ring movement. Preserve this alignment for cylinder fitting.',[184,185])
st('piston-install','Install the piston and new clips','Fit a NEW cylinder gasket, accepted small-end bearing lubricated with engine oil and the dowels. Oil the pin. With the crankcase opening protected by a clean rag, install the piston with its arrow toward the EXHAUST side, then pin and TWO NEW clips. Fully seat each clip and keep its open ends away from the pin-access slit. Account for all old clips/tools and record clip seating/orientation before removing the protective rag.',[177,185],True)
st('cylinder-install','Install the cylinder','Lubricate piston, rings and bore with engine oil. Remove and account for the protective rag; verify no debris/parts remain in the opening. Compress the rings by hand with their gaps still on the locating pins and lower the cylinder carefully over them and onto its dowels/new gasket. Tighten the four nuts progressively in a crisscross pattern to 42 N·m. Do not force a cylinder over an incorrectly aligned ring.',[185],True)
st('pushrod-install','Reconnect the push rod','Restore the push rod and illustrated joint pieces, applying lithium-soap grease at the indicated joint contact surfaces. Insert the owner-tool-kit set pin to support the mechanism while tightening the push-rod bolt to 4.5 N·m. REMOVE and account for the set pin immediately afterward; record its removal.',[176,186],True)
st('housing-close','Close the push-rod housing','Install a NEW power-valve housing gasket and housing; tighten its bolts to 4.5 N·m.',[176,186])
st('head-install','Install the cylinder head','Grease both NEW head O-rings with lithium-soap grease before fitting them. Install dowels and the head. Use six NEW copper washers and tighten the six head nuts progressively in the illustrated crisscross order to 25 N·m.',[176,186])
st('plug-install','Install the spark plug','Check the exact NGK BR8EG plug and 0.5–0.6 mm electrode gap, then install the spark plug to 20 N·m. The detached cap, coolant hose, carburetor, exhaust and engine mounts remain for the separate bike-level refit.',[43,176,186],True)
st('bench-handoff','Record the completed bench work','Record final piston/cylinder grades, all actual clearances, replacement parts, valve smoothness, ring/clip orientation, torque checks and removal of every rag and set pin. Top-end and cylinder power-valve bench assembly are complete within this scope. Keep open external connections protected. Do not start the engine: bike refit, coolant restoration/leak test, correct premix/transmission oil checks and source-specific break-in/post-service checks are separate unfinished handoffs.',[43,176,184,185,186],True)
pages=sorted(set([1,7,43,44]+[n for s in steps for n in s['source_pdf_pages']]))
d={'schema_version':1,'id':'yamaha-2027-yz250-top-end-power-valve-bench-v1','title':'Rebuild the stock two-stroke top end and cylinder power valves — prepared engine','target':{'manufacturer':'Yamaha','model':'YZ250','model_year':2027,'region':'US','variant':'standard'},'scope_confirmed':True,'status':'SOURCE_REVIEW_CANDIDATE','publication_status':'PENDING_INDEPENDENT_REVIEW','component':'engine','affected_components':['engine'],'applicability':{'included':'Exact standard US 2027 YZ250V original two-stroke engine; prepared cold engine with accepted closed lower end.','excluded':['YZ250X, other model years, aftermarket cylinders/pistons or altered ports','Engine removal/refitting, lower end, crankcase YPVS governor and commissioning','Head resurfacing and damaged shaft-seal installation geometry'],'year_inheritance':'NONE'},'entry_state':['Cold drained engine securely prepared on bench; listed external access already completed and recorded.','Stock crankcases remain closed with accepted lower-end condition.'],'exit_state':['Measured and assembled stock top end and cylinder power valves; engine not refitted or commissioned.'],'preflight':['Have the exact owner-tool-kit power-valve set pin before undoing the push rod.','Have accepted exact replacement parts, measuring equipment and source diagrams ready.','Record completed external access and lower-end condition before opening the top end.'],'critical_stop_conditions':['Missing set pin or inability to support the mechanism correctly','Out-of-specification measurements, scoring, broken springs, missing clips or damaged sealing surfaces','Unresolved lower-end contamination or damaged holder/shaft seal'],'required_tools':[{'name':'Secure engine bench fixture; correct hand tools and calibrated torque tools spanning 4–42 N·m'},{'name':'Owner-tool-kit YPVS set pin; piston pin puller 90890-01304 / YU-01304 if needed'},{'name':'Bore gauge, micrometers, straightedge and feeler gauges suitable for the stated clearances'},{'name':'Rounded non-damaging carbon scraper and clean protective rags'}],'required_parts':['Correct grade OEM piston/rings and accepted pin/small-end bearing as required by measured condition','New piston-pin clips (2), cylinder base gasket, cylinder-head O-rings (2), copper head washers (6)','New side-holder O-rings, power-valve cover gasket and housing gasket','Engine oil specified for this two-stroke engine, molybdenum disulfide oil, lithium-soap grease and LOCTITE for holder 2 bolts','Replacement worn/damaged power-valve parts identified during inspection'],'source':{'source_url':URL,'document_sha256':SHA,'document_revision':'D69-2819U-12 / LIT-11626-40-16; US 2027 YZ250V','pdf_pages':pages,'printed_pages':[f'{n}: '+next((x for x in reversed(book[n-1].get_text().splitlines()) if re.fullmatch(r'\d+-\d+',x)),'Symbols (unnumbered)' if n==7 else 'front matter') for n in pages],'review_status':'PENDING_INDEPENDENT_REVIEW','review_note':'Author read exact OEM instructions and rendered exploded assemblies, measurement datums, ring/clip details, power-valve spring/shaft orientation and torque callouts. Independent mechanical review pending.'},'steps':steps,'completeness':'Bounded prepared-engine top-end and cylinder power-valve inspection/renewal/reassembly; engine access, lower end and commissioning remain separate.','remaining_gaps':['Prepared-engine route requires separate verified bike access/refit and commissioning; these are not completed by this guide.','No exact new-ring minimum gap is given by cited source; no filing target inferred.','Crankcase YPVS governor/lower-end overhaul and shaft-seal seating repair are outside this scope.','Physical workshop validation has not been performed.']}
